-- ============================================================================
-- Migration 845: Sand Casting raw materials as real raw_materials columns
-- ============================================================================
-- Generated by scripts/gen_845_promote_sand_casting_raw_materials.js -- do not
-- hand-edit, re-run the generator and diff instead.
--
-- Source: memory/Sand casting/Raw Material/raw_materials.csv (117 materials).
-- Every CSV property is a real column, no JSON. Added columns:
--   usa_name, din_name, en_name, gb_name, jis_name, description, cost_units, base_cost_per_unit_usd, heat_of_fusion_j_kg, specific_heat_rt_j_kg_k, specific_heat_solidus_j_kg_k, thermal_conductivity_w_m_c, cooling_factor_s_mm, ejection_temp_c, injection_temp_c, liquidus_temp_c, solidus_temp_c, yield_loss_factor, data_source
--
-- Name rule: a material keeps its Source Name. If that name already exists under
-- another group (sheet metal or machining), the Sand Casting record is stored as
-- "<Source Name> (Sand Casting)" so both records stay, each with its own cost and
-- properties. Decided in SQL against the live table.
--
-- 1. Adds the new columns (IF NOT EXISTS; existing columns are reused).
-- 2. Inserts the materials not yet present (NOT EXISTS on the stored name).
-- 3. Fills the new columns on the Sand Casting rows already present.
--
-- Idempotent: a second run changes nothing.
-- ============================================================================

-- ── 1. columns
ALTER TABLE raw_materials
  ADD COLUMN IF NOT EXISTS usa_name VARCHAR(255),
  ADD COLUMN IF NOT EXISTS din_name VARCHAR(255),
  ADD COLUMN IF NOT EXISTS en_name VARCHAR(255),
  ADD COLUMN IF NOT EXISTS gb_name VARCHAR(255),
  ADD COLUMN IF NOT EXISTS jis_name VARCHAR(255),
  ADD COLUMN IF NOT EXISTS description TEXT,
  ADD COLUMN IF NOT EXISTS cost_units VARCHAR(50),
  ADD COLUMN IF NOT EXISTS base_cost_per_unit_usd DECIMAL(12,4),
  ADD COLUMN IF NOT EXISTS heat_of_fusion_j_kg DECIMAL(14,2),
  ADD COLUMN IF NOT EXISTS specific_heat_rt_j_kg_k DECIMAL(12,2),
  ADD COLUMN IF NOT EXISTS specific_heat_solidus_j_kg_k DECIMAL(12,2),
  ADD COLUMN IF NOT EXISTS thermal_conductivity_w_m_c DECIMAL(10,3),
  ADD COLUMN IF NOT EXISTS cooling_factor_s_mm DECIMAL(10,4),
  ADD COLUMN IF NOT EXISTS ejection_temp_c DECIMAL(8,2),
  ADD COLUMN IF NOT EXISTS injection_temp_c DECIMAL(8,2),
  ADD COLUMN IF NOT EXISTS liquidus_temp_c DECIMAL(8,2),
  ADD COLUMN IF NOT EXISTS solidus_temp_c DECIMAL(8,2),
  ADD COLUMN IF NOT EXISTS yield_loss_factor DECIMAL(6,3),
  ADD COLUMN IF NOT EXISTS data_source TEXT;

-- ── 2. insert materials not yet present
WITH src AS (
  SELECT v.*,
    CASE WHEN EXISTS (
      SELECT 1 FROM raw_materials rm
      WHERE rm.material = v.material AND rm.material_group IS DISTINCT FROM 'Sand Casting'
